INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss emotions and reason at B2","Use Emotionen und Vernunft vocabulary","Talk about emotional intelligence, the reason-emotion debate, and affective theory"],"explanation":{"intro":"Emotions and reason vocabulary covers the philosophy of emotion, emotional intelligence, and neuroscience of feelings at B2.","culturalNote":"Emotionen und Vernunft: Classical western philosophy privileged Vernunft (reason) over Gefühle (emotions/feelings). Key challenge: neuroscientist António Damásio (Descartes'' Error, 1994 — emotion is necessary for rational decision-making — somatic marker hypothesis). Emotionale Intelligenz (emotional intelligence — Goleman — EQ vs. IQ debate). Key German concepts: Affekt (affect — emotional state — Affektlage), Stimmung (mood — Heidegger''s ''Gestimmtheit''), Gefühl (feeling — more phenomenological), Emotion (emotion — more physiological). Empathieforschung (empathy research — mirror neurons). Germany: Gefühlskultur vs. Sachlichkeit (culture of feelings vs. matter-of-factness)."},"examples":[{"german":"Die klassische Opposition zwischen Vernunft und Gefühl ist eine philosophische Fiktion: Neurowissenschaftliche Forschung zeigt, dass emotionale Prozesse in moralische und rationale Urteile eingebettet sind und Entscheidungen nicht trotz, sondern durch die Einbeziehung affektiver Signale ihre Kohärenz gewinnen.","english":"The classical opposition between reason and feeling is a philosophical fiction: neuroscientific research shows that emotional processes are embedded in moral and rational judgements and decisions gain their coherence not despite but through the inclusion of affective signals."},{"german":"Emotionale Intelligenz ist keine Entgegensetzung zu analytischer Kompetenz, sondern deren Ergänzung: Die Fähigkeit, eigene und fremde Gefühle wahrzunehmen, zu regulieren und produktiv zu nutzen, erhöht soziale Handlungsfähigkeit in einer Weise, die rein kognitive Kompetenz nicht leisten kann.","english":"Emotional intelligence is not an opposition to analytical competence, but its complement: the capacity to perceive, regulate, and productively use one''s own and others'' feelings increases social agency in a way that purely cognitive competence cannot achieve."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss emotion vs. reason, Damasio''s somatic markers, and emotional intelligence at B2."}}',
'{"items":[{"word":"die Fiktion","translation":"fiction","pronunciation":"dee fik-TSYOHN","example":"Philosophische Fiktion."},{"word":"eingebettet","translation":"embedded","pronunciation":"YN-geh-bet-et","example":"In Urteile eingebettet."},{"word":"die Einbeziehung","translation":"inclusion","pronunciation":"dee YN-beh-tsee-oong","example":"Einbeziehung affektiver Signale."},{"word":"die Entgegensetzung","translation":"opposition","pronunciation":"dee ent-GAY-gen-set-soong","example":"Keine Entgegensetzung."},{"word":"regulieren","translation":"to regulate","pronunciation":"reh-goo-LEER-en","example":"Gefühle regulieren."},{"word":"die Handlungsfähigkeit","translation":"agency/ability to act","pronunciation":"dee HAND-loonks-fä-ikh-kyt","example":"Soziale Handlungsfähigkeit."}]}',
'{"title":"Nicht trotz X, sondern durch X — not despite X but through X (inversion of expected role)","pattern":"etwas gelingt nicht trotz X, sondern durch X = something succeeds not despite X but through X (trotz = despite; durch = through — inverts the expected relationship: X is usually seen as obstacle, but here it enables)","explanation":"Nicht trotz X, sondern durch X = not despite X but through X. The pattern inverts the expected causal role of X: typically one might think X is an obstacle (trotz = despite), but the claim is that X is actually enabling (durch = through/by means of). Urteile gewinnen Kohärenz nicht trotz affektiver Signale, sondern durch sie = Decisions gain coherence not despite affective signals, but through them. The inversion is rhetorically powerful: it corrects a misconception and replaces it with the opposite causal claim. Compare: nicht wegen X (not because of X — causal), nicht obwohl X (not although X — concessive), nicht ohne X (not without X — condition).","examples":[{"sentence":"Der Erfolg kam nicht trotz der Krise, sondern durch sie.","translation":"The success came not despite the crisis, but through it."},{"sentence":"Kreativität entsteht nicht trotz Einschränkungen, sondern durch sie.","translation":"Creativity arises not despite constraints, but through them."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Einbeziehung'' means?","options":["inclusion","incorporation","involvement","integration"],"correctAnswer":"inclusion"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The classical opposition between reason and feeling is a philosophical fiction: neuroscientific research shows that emotional processes are embedded in moral and rational judgements and decisions gain their coherence not despite but through the inclusion of affective signals.","options":["Die klassische Opposition zwischen Vernunft und Gefühl ist eine philosophische Fiktion: Neurowissenschaftliche Forschung zeigt, dass emotionale Prozesse in moralische und rationale Urteile eingebettet sind und Entscheidungen nicht trotz, sondern durch die Einbeziehung affektiver Signale ihre Kohärenz gewinnen.","Emotion und Vernunft sind keine Gegensätze — Emotionen helfen rationale Entscheidungen zu treffen.","Neurowissenschaft widerlegt die Idee, dass Vernunft ohne Emotionen auskommt.","Affektive Signale sind notwendig für kohärente Urteile."],"correctAnswer":"Die klassische Opposition zwischen Vernunft und Gefühl ist eine philosophische Fiktion: Neurowissenschaftliche Forschung zeigt, dass emotionale Prozesse in moralische und rationale Urteile eingebettet sind und Entscheidungen nicht trotz, sondern durch die Einbeziehung affektiver Signale ihre Kohärenz gewinnen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Erfolg kam nicht trotz der Krise, sondern ___ sie.","options":["durch","wegen","aufgrund","infolge"],"correctAnswer":"durch"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Creativity arises not despite constraints but through them","wordBankItems":["Kreativität","entsteht","nicht","trotz","Einschränkungen",",","sondern","durch","sie","."],"correctAnswer":"Kreativität entsteht nicht trotz Einschränkungen , sondern durch sie ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Handlungsfähigkeit'' means?","options":["agency/ability to act","capacity","empowerment","competence"],"correctAnswer":"agency/ability to act"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss happiness and wellbeing at B2","Use Glück und Wohlbefinden vocabulary","Talk about wellbeing research, happiness economics, and the limits of GDP"],"explanation":{"intro":"Happiness and wellbeing vocabulary covers wellbeing research, happiness economics, and debates about measuring quality of life at B2.","culturalNote":"Glück und Wohlbefinden: Key distinction in German: Glück as luck (Zufallsglück) vs. Glück as happiness/flourishing (Lebensglück). Ancient: Eudaimonia (Aristotle — flourishing, good life). Hedonie (pleasure-based). Modern wellbeing research: Bruttonationale Glück (Bhutan — Gross National Happiness). Economics: beyond GDP (Stiglitz-Sen-Fitoussi Commission). Key finding: Easterlin Paradox (above a threshold, more income doesn''t = more happiness). Germany: Sozialer Zusammenhalt (social cohesion) as key wellbeing predictor. Positive Psychologie (Martin Seligman). Key German insight: Freude (joy — active), Genuss (pleasure — sensory), Zufriedenheit (contentment — passive), Glückseligkeit (bliss — Kant), Lebensqualität (quality of life)."},"examples":[{"german":"Glück lässt sich nicht auf Lebensstandard reduzieren: Das Easterlin-Paradoxon zeigt, dass jenseits eines Sockelniveaus der materiellen Bedarfsdeckung zusätzliches Einkommen keinen messbaren Beitrag zu subjektivem Wohlbefinden leistet — relative Position, soziale Bindungen und Sinnhaftigkeit erweisen sich als stärkere Prädiktoren.","english":"Happiness cannot be reduced to living standards: the Easterlin Paradox shows that beyond a basic level of material need satisfaction, additional income makes no measurable contribution to subjective wellbeing — relative position, social bonds, and meaningfulness prove to be stronger predictors."},{"german":"Ein Wohlfahrtsbegriff, der sich allein auf wirtschaftliches Wachstum stützt, verfehlt wesentliche Dimensionen des guten Lebens: Zeitwohlstand, Gesundheit, Bildungschancen, soziale Teilhabe und ökologische Integrität sind Aspekte menschlicher Lebensqualität, die kein BIP-Wachstum abbildet.","english":"A welfare concept that is based solely on economic growth misses essential dimensions of the good life: time wealth, health, educational opportunities, social participation, and ecological integrity are aspects of human quality of life that no GDP growth depicts."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss happiness economics, the Easterlin Paradox, and wellbeing beyond GDP at B2."}}',
'{"items":[{"word":"der Sockel","translation":"base/threshold","pronunciation":"dayr ZOK-el","example":"Sockelniveau."},{"word":"messbar","translation":"measurable","pronunciation":"MES-bahr","example":"Messbarer Beitrag."},{"word":"der Prädiktor","translation":"predictor","pronunciation":"dayr prä-DIK-tor","example":"Stärkere Prädiktoren."},{"word":"verfehlen","translation":"to miss/fail to reach","pronunciation":"fer-FAY-len","example":"Dimensionen verfehlen."},{"word":"der Zeitwohlstand","translation":"time wealth","pronunciation":"dayr TSYT-vohl-shtant","example":"Zeitwohlstand."},{"word":"die Teilhabe","translation":"participation","pronunciation":"dee TYL-hah-beh","example":"Soziale Teilhabe."}]}',
'{"title":"Sich als X erweisen — to prove to be X (turning out to be through evidence)","pattern":"etwas/jemand erweist sich als X = something/someone proves/turns out to be X (sich erweisen als = to prove to be, turn out to be — indicates that evidence or experience reveals X to be the case)","explanation":"Sich erweisen als = to prove to be, to turn out to be (erweist sich...als — reflexive; als + adjective/noun). Relative Position und Sinnhaftigkeit erweisen sich als stärkere Prädiktoren = relative position and meaningfulness prove to be stronger predictors. Sich erweisen als implies that the outcome is based on evidence (often research, experience, or events) — more evidential than gelten als (to count as — more accepted/conventional) or betrachtet werden als (to be regarded as — more perspective-based). Compare: sich herausstellen als (to turn out to be — can be neutral), sich zeigen als (to show itself as — more emergence), sich entpuppen als (to turn out to be — often negative surprise).","examples":[{"sentence":"Der Plan erwies sich als nicht umsetzbar.","translation":"The plan proved to be unimplementable."},{"sentence":"Die Maßnahme erwies sich als wirksam.","translation":"The measure proved to be effective."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Messbar'' means?","options":["measurable","quantifiable","observable","detectable"],"correctAnswer":"measurable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Happiness cannot be reduced to living standards: the Easterlin Paradox shows that beyond a basic level of material need satisfaction, additional income makes no measurable contribution to subjective wellbeing — relative position, social bonds, and meaningfulness prove to be stronger predictors.","options":["Glück lässt sich nicht auf Lebensstandard reduzieren: Das Easterlin-Paradoxon zeigt, dass jenseits eines Sockelniveaus der materiellen Bedarfsdeckung zusätzliches Einkommen keinen messbaren Beitrag zu subjektivem Wohlbefinden leistet — relative Position, soziale Bindungen und Sinnhaftigkeit erweisen sich als stärkere Prädiktoren.","Mehr Geld macht nicht glücklicher — soziale Beziehungen sind wichtiger.","Das Easterlin-Paradoxon zeigt, dass Einkommen ab einem Punkt nicht mehr glücklicher macht.","Glück hängt von Sinn, Beziehungen und sozialer Position ab, nicht von Geld."],"correctAnswer":"Glück lässt sich nicht auf Lebensstandard reduzieren: Das Easterlin-Paradoxon zeigt, dass jenseits eines Sockelniveaus der materiellen Bedarfsdeckung zusätzliches Einkommen keinen messbaren Beitrag zu subjektivem Wohlbefinden leistet — relative Position, soziale Bindungen und Sinnhaftigkeit erweisen sich als stärkere Prädiktoren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Plan erwies sich als nicht ___.","options":["umsetzbar","machbar","realisierbar","durchführbar"],"correctAnswer":"umsetzbar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The measure proved to be effective","wordBankItems":["Die","Maßnahme","erwies","sich","als","wirksam","."],"correctAnswer":"Die Maßnahme erwies sich als wirksam ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Teilhabe'' means?","options":["participation","inclusion","sharing","belonging"],"correctAnswer":"participation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health and lifestyle at B2","Use Gesundheit und Lebensführung vocabulary","Talk about Germany''s health system, preventive health, and healthy lifestyle debates"],"explanation":{"intro":"Health and lifestyle vocabulary covers Germany''s healthcare system, preventive medicine, and debates about individual vs. structural determinants of health at B2.","culturalNote":"Gesundheit und Lebensführung: Germany has a universal healthcare system (gesetzliche Krankenversicherung — statutory health insurance — Bismarck 1883 — world''s oldest). Key: Krankenkassen (health insurance funds — ~100), privatärztliche vs. kassärztliche Versorgung (private vs. statutory). Key figures: Gesundheitsminister Karl Lauterbach. Key issues: Krankenhausreform (hospital reform — Lauterbach 2024), Fachkräftemangel Pflege (nursing shortage), Präventionslücke (prevention gap — Germany spends little on prevention vs. curative). Lifestyle factors: Übergewicht (obesity — rising), Rauchen (smoking — still high), Alkohol. Social determinants of health: health inequality (Gesundheitsungleichheit) — lower income = worse health."},"examples":[{"german":"Gesundheit ist kein rein individuelles Projekt, sondern durch soziale Determinanten strukturiert: Bildungsgrad, Einkommenshöhe, Arbeitsbedingungen und Wohnumgebung beeinflussen Gesundheitschancen systematisch und in einer Weise, die individuelle Verhaltensänderungen allein nicht aufheben können.","english":"Health is not a purely individual project, but is structured by social determinants: level of education, income level, working conditions, and living environment systematically influence health opportunities in a way that individual behavioural changes alone cannot undo."},{"german":"Das Gesundheitssystem steht vor einem Paradigmenwechsel: Weg von kurativer Medizin, die Erkrankungen behandelt, hin zu präventiver Strategie, die ihre Entstehung verhindert — ein Ansatz, der nicht nur wirtschaftlich sinnvoller ist, sondern auch soziale Ungleichheiten in der Gesundheitsversorgung systematisch verringert.","english":"The health system faces a paradigm shift: away from curative medicine that treats diseases, towards a preventive strategy that prevents their development — an approach that is not only more economically sensible, but also systematically reduces social inequalities in healthcare."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s healthcare system, preventive medicine, and social determinants of health at B2."}}',
'{"items":[{"word":"die Determinante","translation":"determinant","pronunciation":"dee deh-ter-mi-NAN-teh","example":"Soziale Determinanten."},{"word":"aufheben","translation":"to undo/cancel out","pronunciation":"OWF-hay-ben","example":"Ungleichheiten aufheben."},{"word":"der Paradigmenwechsel","translation":"paradigm shift","pronunciation":"dayr pah-rah-DIG-men-vek-sel","example":"Paradigmenwechsel im Gesundheitswesen."},{"word":"kurativ","translation":"curative","pronunciation":"koo-rah-TEEF","example":"Kurativ vs. präventiv."},{"word":"präventiv","translation":"preventive","pronunciation":"prä-ven-TEEF","example":"Präventive Strategie."},{"word":"verringern","translation":"to reduce","pronunciation":"fer-RING-ern","example":"Ungleichheiten verringern."}]}',
'{"title":"Weg von X, hin zu Y — away from X, towards Y (directional transition)","pattern":"weg von X, hin zu Y = away from X, towards Y (weg von = away from; hin zu = towards — directional adverbials marking a shift in orientation)","explanation":"Weg von X, hin zu Y = away from X, towards Y. Marks a directional transition or strategic reorientation: what is being left behind (weg von) and what is being moved towards (hin zu). Weg von kurativer Medizin, hin zu präventiver Strategie = away from curative medicine, towards a preventive strategy. The pattern communicates change of direction, often in policy or strategy. Compare: von X zu Y (from X to Y — simpler transition), statt X lieber Y (rather Y than X — preference), X durch Y ersetzen (to replace X with Y — more active), von X auf Y umschwenken (to switch from X to Y — more sudden).","examples":[{"sentence":"Weg von fossilen Energien, hin zu erneuerbaren Quellen.","translation":"Away from fossil energies, towards renewable sources."},{"sentence":"Weg vom Einzelkämpfer, hin zum Teamansatz.","translation":"Away from the lone fighter, towards the team approach."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kurativ'' means?","options":["curative","healing","therapeutic","restorative"],"correctAnswer":"curative"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Health is not a purely individual project, but is structured by social determinants: level of education, income level, working conditions, and living environment systematically influence health opportunities in a way that individual behavioural changes alone cannot undo.","options":["Gesundheit ist kein rein individuelles Projekt, sondern durch soziale Determinanten strukturiert: Bildungsgrad, Einkommenshöhe, Arbeitsbedingungen und Wohnumgebung beeinflussen Gesundheitschancen systematisch und in einer Weise, die individuelle Verhaltensänderungen allein nicht aufheben können.","Gesundheit hängt nicht nur vom Verhalten ab, sondern auch von sozialen Faktoren.","Soziale Ungleichheit schlägt sich direkt in Gesundheitsungleichheit nieder.","Individuelles Gesundheitsverhalten kann strukturelle Ungleichheiten nicht ausgleichen."],"correctAnswer":"Gesundheit ist kein rein individuelles Projekt, sondern durch soziale Determinanten strukturiert: Bildungsgrad, Einkommenshöhe, Arbeitsbedingungen und Wohnumgebung beeinflussen Gesundheitschancen systematisch und in einer Weise, die individuelle Verhaltensänderungen allein nicht aufheben können."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Weg von fossilen Energien, hin zu erneuerbaren ___.","options":["Quellen","Energien","Ressourcen","Alternativen"],"correctAnswer":"Quellen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Away from the lone fighter towards the team approach","wordBankItems":["Weg","vom","Einzelkämpfer",",","hin","zum","Teamansatz","."],"correctAnswer":"Weg vom Einzelkämpfer , hin zum Teamansatz ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verringern'' means?","options":["to reduce","to diminish","to decrease","to lessen"],"correctAnswer":"to reduce"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss pain and suffering at B2","Use Schmerz und Leiden vocabulary","Talk about chronic pain, palliative care, and ethics of suffering"],"explanation":{"intro":"Pain and suffering vocabulary covers chronic pain medicine, palliative care, and philosophical dimensions of suffering at B2.","culturalNote":"Schmerz und Leiden: Germany: strong palliative care movement (Palliativversorgung — since 1983 — first hospice in Aachen), hospice movement, Sterbebegleitung (accompaniment in dying). Key legal debates: Sterbehilfe (euthanasia): Germany distinguishes Passive Sterbehilfe (passive euthanasia — allowed), Aktive Sterbehilfe (active euthanasia — illegal), Beihilfe zum Suizid (assisted suicide — BVerfG 2020: criminalisation unconstitutional — right to determine one''s own death). Chronic pain: 15 million people in Germany with chronic pain — Schmerztherapie (pain therapy) — interdisciplinary pain medicine. Philosophical: Simone Weil (creative suffering), Viktor Frankl (Logotherapie — finding meaning through suffering — Holocaust survivor)."},"examples":[{"german":"Schmerz hat eine epistemische Dimension, die ihn von anderen körperlichen Zuständen unterscheidet: Er ist privat und unübertragbar — kein Außenstehender kann ihn direkt erfahren, und selbst die ausgefeilteste Messmethodik bleibt auf subjektive Berichte angewiesen, die keine objektive Verifikation zulassen.","english":"Pain has an epistemic dimension that distinguishes it from other physical states: it is private and non-transferable — no outsider can directly experience it, and even the most refined measurement methodology remains dependent on subjective reports that permit no objective verification."},{"german":"Palliativmedizin beruht auf der Einsicht, dass medizinisches Handeln nicht ausschließlich auf Heilung ausgerichtet sein kann: Wenn Heilung nicht mehr möglich ist, bleibt die Aufgabe, Leiden zu lindern, Würde zu erhalten und Sterbenden den Raum zu geben, den letzten Lebensabschnitt nach eigenen Wertvorstellungen zu gestalten.","english":"Palliative medicine rests on the insight that medical action cannot be directed exclusively at healing: when healing is no longer possible, the task remains to alleviate suffering, preserve dignity, and give the dying the space to shape the final phase of life according to their own values."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss chronic pain, palliative care, and Germany''s euthanasia debate at B2."}}',
'{"items":[{"word":"epistemisch","translation":"epistemic","pronunciation":"eh-pis-TAY-mish","example":"Epistemische Dimension."},{"word":"unübertragbar","translation":"non-transferable","pronunciation":"oon-ü-ber-TRAHK-bahr","example":"Privat und unübertragbar."},{"word":"ausgefeit","translation":"refined","pronunciation":"OWS-geh-fy-felt","example":"Ausgefeilteste Methodik."},{"word":"lindern","translation":"to alleviate","pronunciation":"LIN-dern","example":"Leiden lindern."},{"word":"der Lebensabschnitt","translation":"phase of life","pronunciation":"dayr LAY-bens-ab-shnit","example":"Letzter Lebensabschnitt."},{"word":"gestalten","translation":"to shape","pronunciation":"geh-SHTAL-ten","example":"Leben gestalten."}]}',
'{"title":"Auf X angewiesen bleiben — to remain dependent on X (necessary dependency)","pattern":"etwas bleibt auf X angewiesen = something remains dependent on X (angewiesen sein auf = to be dependent on — adjective: angewiesen; auf + accusative marks what one depends on)","explanation":"Auf X angewiesen sein = to be dependent on X (angewiesen + auf + accusative). Bleibt auf subjektive Berichte angewiesen = remains dependent on subjective reports (can''t escape this dependency). Angewiesen sein = dependent on (not a chosen dependency but a structural necessity). Often used to mark an unavoidable epistemic or practical constraint: science is dependent on reports, developing countries are dependent on aid. Compare: von X abhängen (to depend on X — more general), ohne X nicht auskommen (to be unable to manage without X — more informal), auf X setzen (to rely on/bet on X — more voluntary).","examples":[{"sentence":"Die Forschung bleibt auf externe Finanzierung angewiesen.","translation":"The research remains dependent on external funding."},{"sentence":"Er ist auf regelmäßige Medikamente angewiesen.","translation":"He is dependent on regular medication."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Lindern'' means?","options":["to alleviate","to relieve","to ease","to soothe"],"correctAnswer":"to alleviate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Pain has an epistemic dimension that distinguishes it from other physical states: it is private and non-transferable — no outsider can directly experience it, and even the most refined measurement methodology remains dependent on subjective reports that permit no objective verification.","options":["Schmerz hat eine epistemische Dimension, die ihn von anderen körperlichen Zuständen unterscheidet: Er ist privat und unübertragbar — kein Außenstehender kann ihn direkt erfahren, und selbst die ausgefeilteste Messmethodik bleibt auf subjektive Berichte angewiesen, die keine objektive Verifikation zulassen.","Schmerz ist subjektiv und kann von außen nicht wirklich gemessen werden.","Schmerzmessung bleibt immer auf Patientenberichte angewiesen.","Die Privatheit des Schmerzes macht seine Messung schwierig."],"correctAnswer":"Schmerz hat eine epistemische Dimension, die ihn von anderen körperlichen Zuständen unterscheidet: Er ist privat und unübertragbar — kein Außenstehender kann ihn direkt erfahren, und selbst die ausgefeilteste Messmethodik bleibt auf subjektive Berichte angewiesen, die keine objektive Verifikation zulassen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Forschung bleibt auf externe Finanzierung ___.","options":["angewiesen","abhängig","angewiesen","gebunden"],"correctAnswer":"angewiesen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is dependent on regular medication","wordBankItems":["Er","ist","auf","regelmäßige","Medikamente","angewiesen","."],"correctAnswer":"Er ist auf regelmäßige Medikamente angewiesen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gestalten'' means?","options":["to shape","to design","to form","to create"],"correctAnswer":"to shape"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss death and dying at B2","Use Tod und Sterben vocabulary","Talk about death in German culture, mortality, and Sterbebegleitung"],"explanation":{"intro":"Death and dying vocabulary covers mortality, death rituals, and Germany''s approach to end-of-life care at B2.","culturalNote":"Tod und Sterben: Death taboo in modern western culture (Ariès: ''invisible death'' — moved from home to hospital). Germany: 900,000 deaths p.a. Hospiz (hospice — since 1983 — more than 1,500 facilities). Sterbebegleitung (dying accompaniment — companion). Patientenverfügung (advance directive — Patienten-Verfügung — legally binding — allowing refusal of treatment). Organspendeausweis (donor card — Germany: opt-in — low rates vs. Spain opt-out). Sterbehilfe debate (see lesson 694). Trauerarbeit (grief work — Kübler-Ross stages). Key philosophical: Heidegger''s Sein-zum-Tode (being-towards-death — authentic existence through awareness of mortality). Memorial culture: Todesanzeigen (death notices in newspapers), Trauerfeiern (funeral services)."},"examples":[{"german":"Heideggers Begriff des Sein-zum-Tode zielt nicht auf eine morbide Beschäftigung mit dem Tod, sondern auf eine existenzielle Orientierung: Das Bewusstsein der eigenen Endlichkeit befreit vom Diktat des ''Man'' — des anonymen sozialen Konformismus — und ermöglicht eine authentischere Lebensführung.","english":"Heidegger''s concept of being-towards-death does not aim at a morbid preoccupation with death, but at an existential orientation: awareness of one''s own finitude liberates from the dictate of the ''one'' — of anonymous social conformism — and enables a more authentic way of living."},{"german":"Die Sterbebegleitung ist eine Form der Zuwendung, die das biomedizinische Modell des ''Kampfes gegen den Tod'' hinter sich lässt: Sie bejaht die Begrenztheit des Lebens und konzentriert sich auf Schmerzfreiheit, menschliche Würde und die Ermöglichung eines selbstbestimmten Sterbensprozesses.","english":"Dying accompaniment is a form of care that leaves behind the biomedical model of ''fighting against death'': it affirms the limitation of life and focuses on freedom from pain, human dignity, and the enabling of a self-determined dying process."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Heidegger''s being-towards-death, hospice care, and Germany''s death culture at B2."}}',
'{"items":[{"word":"die Endlichkeit","translation":"finitude","pronunciation":"dee END-likh-kyt","example":"Bewusstsein der Endlichkeit."},{"word":"das Diktat","translation":"dictate","pronunciation":"dahs dik-TAHT","example":"Diktat des ''Man''."},{"word":"der Konformismus","translation":"conformism","pronunciation":"dayr kon-for-MIS-moos","example":"Sozialer Konformismus."},{"word":"bejahen","translation":"to affirm","pronunciation":"beh-YAH-en","example":"Begrenztheit bejahen."},{"word":"die Begrenztheit","translation":"limitation","pronunciation":"dee beh-GRENTST-hyt","example":"Begrenztheit des Lebens."},{"word":"selbstbestimmt","translation":"self-determined","pronunciation":"ZELPS-beh-shtimt","example":"Selbstbestimmtes Sterben."}]}',
'{"title":"Hinter sich lassen — to leave behind (leaving a paradigm or approach)","pattern":"etwas lässt X hinter sich = something leaves X behind (hinter sich lassen = to leave behind — separable: lässt...hinter sich; marks what is being surpassed or transcended)","explanation":"Hinter sich lassen = to leave behind (separable: lässt...hinter sich). Das Modell lässt den ''Kampf gegen den Tod'' hinter sich = The model leaves ''fighting against death'' behind. The phrase marks that something is being transcended, surpassed, or abandoned: not just ''not doing X'' but actively moving past X. Compare: überwinden (to overcome — more active struggle), aufgeben (to give up — more giving up on something), ablösen (to replace — more about substitution), hinter sich bringen (to get through/past — more about finishing a difficult task).","examples":[{"sentence":"Die Bewegung hat die alten Ideen hinter sich gelassen.","translation":"The movement has left the old ideas behind."},{"sentence":"Er hat seinen Schmerz hinter sich gelassen.","translation":"He has left his pain behind."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Bejahen'' means?","options":["to affirm","to accept","to embrace","to acknowledge"],"correctAnswer":"to affirm"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Heidegger''s concept of being-towards-death does not aim at a morbid preoccupation with death, but at an existential orientation: awareness of one''s own finitude liberates from the dictate of the ''one'' — of anonymous social conformism — and enables a more authentic way of living.","options":["Heideggers Begriff des Sein-zum-Tode zielt nicht auf eine morbide Beschäftigung mit dem Tod, sondern auf eine existenzielle Orientierung: Das Bewusstsein der eigenen Endlichkeit befreit vom Diktat des ''Man'' — des anonymen sozialen Konformismus — und ermöglicht eine authentischere Lebensführung.","Heidegger sieht das Bewusstsein der Sterblichkeit als Grundlage authentischer Existenz.","Sein-zum-Tode meint nicht Todesangst, sondern Befreiung zu einem echten Leben.","Die Endlichkeit des Lebens zu akzeptieren ermöglicht ein authentischeres Dasein."],"correctAnswer":"Heideggers Begriff des Sein-zum-Tode zielt nicht auf eine morbide Beschäftigung mit dem Tod, sondern auf eine existenzielle Orientierung: Das Bewusstsein der eigenen Endlichkeit befreit vom Diktat des ''Man'' — des anonymen sozialen Konformismus — und ermöglicht eine authentischere Lebensführung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Bewegung hat die alten Ideen hinter sich ___.","options":["gelassen","gebracht","geworfen","gestellt"],"correctAnswer":"gelassen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He has left his pain behind","wordBankItems":["Er","hat","seinen","Schmerz","hinter","sich","gelassen","."],"correctAnswer":"Er hat seinen Schmerz hinter sich gelassen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Selbstbestimmt'' means?","options":["self-determined","autonomous","independent","self-directed"],"correctAnswer":"self-determined"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss friendship and love at B2","Use Freundschaft und Liebe vocabulary","Talk about the sociology and philosophy of friendship, love, and intimate relationships"],"explanation":{"intro":"Friendship and love vocabulary covers the philosophy and sociology of love, friendship, and intimacy at B2.","culturalNote":"Freundschaft und Liebe: Key distinctions: Eros (romantic/erotic love — Plato), Philia (friendship — Aristotle — Nikomachische Ethik: the friend is another self), Agape (unconditional/spiritual love — Christianity), Storge (familial love). German: Liebe (love), Freundschaft (friendship), Zuneigung (affection), Verbundenheit (connectedness). Sociology: Niklas Luhmann (Liebe als Passion — love as code — 1982). Intimität (intimacy). Digitale Partnerwahl (digital partner selection — Tinder, Bumble — algorithmische Liebe). Ehe (marriage) — same-sex marriage (Ehe für alle — 2017 Germany). Bindungstheorie (attachment theory — Bowlby). Key philosophical: love as recognition (Honneth) — ''Liebe macht sehend'' (love makes one see)."},"examples":[{"german":"Aristoteles unterscheidet drei Arten der Freundschaft nach dem Grundmotiv: Nützlichkeitsfreundschaft, Lustfreundschaft und die vollkommene Freundschaft unter Tugendhaften, die er als stabilste und tiefste Form betrachtet — weil sie nicht an wechselnde Umstände gebunden, sondern im Charakter des anderen selbst begründet ist.","english":"Aristotle distinguishes three kinds of friendship according to the underlying motive: friendship of utility, friendship of pleasure, and the perfect friendship among the virtuous, which he regards as the most stable and deepest form — because it is not bound to changing circumstances, but is founded in the other''s character itself."},{"german":"Liebe ist kein Zustand, sondern eine Praxis: Sie muss täglich erneuert, kommuniziert und durch konkrete Handlungen bestätigt werden — eine Einsicht, die die romantische Vorstellung der ''ewigen Liebe als unvergängliches Gefühl'' durch das nüchternere Bild der Liebe als fortdauernde Entscheidung ersetzt.","english":"Love is not a state but a practice: it must be daily renewed, communicated, and confirmed through concrete actions — an insight that replaces the romantic notion of ''eternal love as an imperishable feeling'' with the more sober image of love as an enduring decision."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Aristotle''s friendship types, love as practice, and German intimate life at B2."}}',
'{"items":[{"word":"vollkommen","translation":"perfect/complete","pronunciation":"FOL-ko-men","example":"Vollkommene Freundschaft."},{"word":"tugendhaft","translation":"virtuous","pronunciation":"TOO-gent-haft","example":"Tugendhafter Mensch."},{"word":"begründet in","translation":"founded in","pronunciation":"beh-GRÜN-det in","example":"Im Charakter begründet."},{"word":"unvergänglich","translation":"imperishable","pronunciation":"oon-fer-GENG-likh","example":"Unvergängliches Gefühl."},{"word":"ersetzen durch","translation":"to replace with","pronunciation":"er-ZET-tsen doorkh","example":"Vorstellung ersetzen durch."},{"word":"fortdauernd","translation":"enduring","pronunciation":"FORT-dow-ernd","example":"Fortdauernde Entscheidung."}]}',
'{"title":"Nicht X, sondern Y ersetzen — X by Y replacing (conceptual substitution)","pattern":"etwas ersetzt X durch Y = something replaces X with/by Y (ersetzen + accusative + durch + accusative: X is replaced BY Y — durch marks the instrument of replacement)","explanation":"Ersetzen durch = to replace with/by (ersetzen takes two accusative objects: the thing replaced and the replacement, linked by durch). Die Einsicht ersetzt die romantische Vorstellung durch das nüchternere Bild = The insight replaces the romantic notion by/with the more sober image. Note: X durch Y ersetzen = X (what is replaced) durch Y (what replaces it). Passive: X wird durch Y ersetzt = X is replaced by Y. Compare: X ablösen (to supersede/replace — implies sequence in time), X verdrängen (to displace X — implies conflict), an die Stelle von X treten (to take the place of X — more neutral substitution), X aufheben (to sublate/abolish X — dialectical, Hegel).","examples":[{"sentence":"Die neue Methode ersetzt die alte durch ein effizienteres Verfahren.","translation":"The new method replaces the old one with a more efficient procedure."},{"sentence":"Er ersetzte seinen Laptop durch ein neueres Modell.","translation":"He replaced his laptop with a newer model."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unvergänglich'' means?","options":["imperishable","eternal","immortal","everlasting"],"correctAnswer":"imperishable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Love is not a state but a practice: it must be daily renewed, communicated, and confirmed through concrete actions — an insight that replaces the romantic notion of ''eternal love as an imperishable feeling'' with the more sober image of love as an enduring decision.","options":["Liebe ist kein Zustand, sondern eine Praxis: Sie muss täglich erneuert, kommuniziert und durch konkrete Handlungen bestätigt werden — eine Einsicht, die die romantische Vorstellung der ''ewigen Liebe als unvergängliches Gefühl'' durch das nüchternere Bild der Liebe als fortdauernde Entscheidung ersetzt.","Liebe ist keine Emotion, sondern eine täglich erneuerte Entscheidung.","Liebe braucht täglich Bestätigung durch Handlungen, nicht nur Gefühle.","Die romantische Vorstellung ewiger Liebe weicht einem realistischeren Bild."],"correctAnswer":"Liebe ist kein Zustand, sondern eine Praxis: Sie muss täglich erneuert, kommuniziert und durch konkrete Handlungen bestätigt werden — eine Einsicht, die die romantische Vorstellung der ''ewigen Liebe als unvergängliches Gefühl'' durch das nüchternere Bild der Liebe als fortdauernde Entscheidung ersetzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die neue Methode ersetzt die alte durch ein effizienteres ___.","options":["Verfahren","Vorgehen","Methode","System"],"correctAnswer":"Verfahren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He replaced his laptop with a newer model","wordBankItems":["Er","ersetzte","seinen","Laptop","durch","ein","neueres","Modell","."],"correctAnswer":"Er ersetzte seinen Laptop durch ein neueres Modell ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Begründet in'' means?","options":["founded in","grounded in","rooted in","based in"],"correctAnswer":"founded in"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002b9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the changing family at B2","Use Familie im Wandel vocabulary","Talk about family structures, Germany''s family policy, and demographic change"],"explanation":{"intro":"Changing family vocabulary covers Germany''s family policy, diverse family structures, and demographic pressures at B2.","culturalNote":"Familie im Wandel: Germany: historically male-breadwinner model (Ernährermodell) — slow transition. Familienpolitik (family policy): Elterngeld (parental leave — 12-14 months shared), Kindergeld (child benefit), Kita-Plätze (childcare places — shortage). Key: Vereinbarkeit von Familie und Beruf (work-family balance — still difficult). Diverse Familien: Patchworkfamilien (blended families), Regenbogenfamilien (rainbow families — same-sex parents), Alleinerziehende (single parents — 1.5 million in Germany — 90% women), Kinderlosigkeit (childlessness — ~20% German women born 1967-1976 childless). Demographischer Wandel (demographic change — ageing society, falling birth rate). Subsidiarität (subsidiarity — family first, then state) vs. Krippenausbau (childcare expansion)."},"examples":[{"german":"Die Familie ist keine unveränderliche Naturgegebenheit, sondern eine historisch variable Organisationsform des menschlichen Zusammenlebens: Kernfamilie, Großfamilie, Patchworkfamilie und Regenbogenfamilie sind Varianten, die unterschiedliche gesellschaftliche Anforderungen, Wertvorstellungen und Möglichkeiten verkörpern.","english":"The family is not an immutable natural given, but a historically variable organisational form of human co-living: nuclear family, extended family, blended family, and rainbow family are variants that embody different societal requirements, values, and possibilities."},{"german":"Die Vereinbarkeit von Familie und Beruf ist in Deutschland strukturell unterfinanziert: Mangelnde Betreuungsinfrastruktur, Teilzeit-Karrierefallen und kulturelle Erwartungen an Mütter erzeugen eine systematische Benachteiligung von Frauen, die trotz formaler Gleichstellung ihre Berufslaufbahn häufig unterbrechen oder reduzieren.","english":"The reconciliation of family and work in Germany is structurally underfunded: insufficient childcare infrastructure, part-time career traps, and cultural expectations of mothers produce a systematic disadvantage of women, who despite formal equal standing frequently interrupt or reduce their career paths."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s family policy, work-family balance, and changing family structures at B2."}}',
'{"items":[{"word":"die Naturalgegebenheit","translation":"natural given","pronunciation":"dee nah-too-RAL-geh-gay-ben-hyt","example":"Unveränderliche Naturgegebenheit."},{"word":"die Betreuungsinfrastruktur","translation":"childcare infrastructure","pronunciation":"dee beh-TROY-oonks-in-frah-shtru-ktur","example":"Betreuungsinfrastruktur."},{"word":"die Karrierefalle","translation":"career trap","pronunciation":"dee kah-RYEH-reh-fal-eh","example":"Teilzeit-Karrierefalle."},{"word":"erzeugen","translation":"to produce/generate","pronunciation":"er-TSOY-gen","example":"Benachteiligung erzeugen."},{"word":"die Benachteiligung","translation":"disadvantage","pronunciation":"dee beh-NAKHH-ty-li-goong","example":"Systematische Benachteiligung."},{"word":"unterbrechen","translation":"to interrupt","pronunciation":"oon-ter-BREKH-en","example":"Berufslaufbahn unterbrechen."}]}',
'{"title":"Trotz formaler Gleichstellung + Realität — formal equality vs. lived reality","pattern":"trotz formaler Gleichstellung + negative outcome = despite formal equal standing + negative result (trotz = despite — + genitive; formale Gleichstellung = formal/legal equality; marks the gap between law and social reality)","explanation":"Trotz + genitive = despite. Trotz formaler Gleichstellung = despite formal equal standing (genitive: formaler Gleichstellung). The pattern marks the gap between formal/legal status and social reality: the law says equal, but reality shows inequality. Frequently used in gender politics, anti-discrimination discourse: ''formally equal but structurally disadvantaged.'' Compare: obwohl formal gleichgestellt... (although formally equated... — subordinate clause version), de jure vs. de facto (Latin legal terms for the same gap), auf dem Papier vs. in der Praxis (on paper vs. in practice — more everyday).","examples":[{"sentence":"Trotz formaler Anerkennung ihrer Rechte werden Minderheiten weiterhin diskriminiert.","translation":"Despite formal recognition of their rights, minorities continue to be discriminated against."},{"sentence":"Trotz gesetzlicher Gleichstellung verdienen Frauen weniger.","translation":"Despite legal equal standing, women earn less."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Benachteiligung'' means?","options":["disadvantage","discrimination","inequality","marginalisation"],"correctAnswer":"disadvantage"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The reconciliation of family and work in Germany is structurally underfunded: insufficient childcare infrastructure, part-time career traps, and cultural expectations of mothers produce a systematic disadvantage of women, who despite formal equal standing frequently interrupt or reduce their career paths.","options":["Die Vereinbarkeit von Familie und Beruf ist in Deutschland strukturell unterfinanziert: Mangelnde Betreuungsinfrastruktur, Teilzeit-Karrierefallen und kulturelle Erwartungen an Mütter erzeugen eine systematische Benachteiligung von Frauen, die trotz formaler Gleichstellung ihre Berufslaufbahn häufig unterbrechen oder reduzieren.","Frauen werden trotz formaler Gleichstellung strukturell benachteiligt.","Die Vereinbarkeit von Familie und Beruf scheitert an mangelnder Kinderbetreuung.","Mütter müssen in Deutschland oft zwischen Familie und Karriere wählen."],"correctAnswer":"Die Vereinbarkeit von Familie und Beruf ist in Deutschland strukturell unterfinanziert: Mangelnde Betreuungsinfrastruktur, Teilzeit-Karrierefallen und kulturelle Erwartungen an Mütter erzeugen eine systematische Benachteiligung von Frauen, die trotz formaler Gleichstellung ihre Berufslaufbahn häufig unterbrechen oder reduzieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Trotz gesetzlicher Gleichstellung verdienen Frauen ___.","options":["weniger","immer noch weniger","kaum mehr","deutlich weniger"],"correctAnswer":"weniger"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Despite formal recognition of their rights minorities continue to be discriminated against","wordBankItems":["Trotz","formaler","Anerkennung","ihrer","Rechte","werden","Minderheiten","weiterhin","diskriminiert","."],"correctAnswer":"Trotz formaler Anerkennung ihrer Rechte werden Minderheiten weiterhin diskriminiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unterbrechen'' means?","options":["to interrupt","to pause","to break off","to suspend"],"correctAnswer":"to interrupt"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ba',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss childhood and upbringing at B2","Use Kindheit und Erziehung vocabulary","Talk about child development, educational philosophy, and parenting in Germany"],"explanation":{"intro":"Childhood and upbringing vocabulary covers child development, educational philosophy, and German parenting culture at B2.","culturalNote":"Kindheit und Erziehung: Germany: Erziehungsstile (parenting styles — authoritative/democratic vs. authoritarian). Key reform: Kinderrechte im Grundgesetz (children''s rights in Basic Law — 2021 amendment, Art. 6). Bodily punishment: banned 2000 (Recht auf gewaltfreie Erziehung). Waldorf (Rudolf Steiner), Montessori — alternative school concepts. Key debate: Helikopter-Eltern (helicopter parents — overprotective), Tigermum (tiger mother — Amy Chua). Frühkindliche Bildung (early childhood education — key debate: Kita-Qualität). Kindheitsforschung (childhood research). Key figure: Maria Montessori (''follow the child''). Key concept: Bindungstheorie (attachment theory — secure/insecure attachment — Bowlby/Ainsworth). Sozialisation (socialisation — primary/secondary). Peer groups."},"examples":[{"german":"Die pädagogische Debatte um den richtigen Erziehungsstil kreist um eine Grundfrage: Wieviel Struktur braucht ein Kind, und ab wann hemmt sie Autonomie und Kreativität? Die empirische Entwicklungspsychologie zeigt, dass autoritativer Erziehungsstil — der Wärme mit klaren Grenzen verbindet — bessere Entwicklungsergebnisse produziert als autoritärer oder permissiver Stil.","english":"The pedagogical debate about the right parenting style revolves around a basic question: how much structure does a child need, and from when does it inhibit autonomy and creativity? Empirical developmental psychology shows that authoritative parenting style — which combines warmth with clear boundaries — produces better developmental outcomes than authoritarian or permissive style."},{"german":"Kindheit ist keine vorübergehende Phase auf dem Weg zum Erwachsenenstatus, sondern eine eigenwertige Lebensphase mit eigener Logik und eigenen Rechten: Das Kindeswohl ist ein eigenständiges Rechtsgut, das Elternrechte und staatliche Interessen legitimerweise begrenzen darf.","english":"Childhood is not a transitory phase on the way to adult status, but a valuable phase of life in its own right with its own logic and its own rights: child welfare is an independent legal good that may legitimately limit parental rights and state interests."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss parenting styles, attachment theory, and children''s rights in Germany at B2."}}',
'{"items":[{"word":"hemmen","translation":"to inhibit","pronunciation":"HEM-en","example":"Kreativität hemmen."},{"word":"der Erziehungsstil","translation":"parenting style","pronunciation":"dayr er-TSEE-oonks-shteel","example":"Autoritativer Erziehungsstil."},{"word":"eigenwertig","translation":"valuable in its own right","pronunciation":"EYE-gen-ver-tikh","example":"Eigenwertige Lebensphase."},{"word":"das Rechtsgut","translation":"legal good","pronunciation":"dahs REKHTS-goot","example":"Eigenständiges Rechtsgut."},{"word":"legitimerweise","translation":"legitimately","pronunciation":"leh-gi-tee-mer-VYE-zeh","example":"Legitimerweise begrenzen."},{"word":"begrenzen","translation":"to limit","pronunciation":"beh-GREN-tsen","example":"Elternrechte begrenzen."}]}',
'{"title":"In eigener Logik und eigenen Rechten — in its own logic and its own rights (self-constitution of a category)","pattern":"X hat eine eigene Logik und eigene Rechte = X has its own logic and its own rights (eigen- = one''s own — stresses that X is not merely defined by relation to Y; eigenständig (independent) and eigene Logik reinforce autonomy of the category)","explanation":"Eigen- = one''s own (adjective: eigenständig = independent, eigene Logik = its own logic). The pattern asserts the autonomy of a domain or category against reduction to another: childhood is not defined by (relative to) adulthood, but has its own logic. Key grammar: eigen- declines like a regular adjective (eigene, eigenen, etc.). Compare: an sich (in itself — philosophical — Kant), für sich (for itself — independent existence), in sich (within itself — self-contained), selbst (itself/very — emphasiser), genuin (genuinely/inherently).","examples":[{"sentence":"Kunst hat eine eigene Logik, die sich ökonomischem Kalkül entzieht.","translation":"Art has its own logic that eludes economic calculation."},{"sentence":"Jede Wissenschaft hat ihre eigenen Methoden und Maßstäbe.","translation":"Each science has its own methods and standards."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Hemmen'' means?","options":["to inhibit","to restrict","to prevent","to suppress"],"correctAnswer":"to inhibit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Childhood is not a transitory phase on the way to adult status, but a valuable phase of life in its own right with its own logic and its own rights: child welfare is an independent legal good that may legitimately limit parental rights and state interests.","options":["Kindheit ist keine vorübergehende Phase auf dem Weg zum Erwachsenenstatus, sondern eine eigenwertige Lebensphase mit eigener Logik und eigenen Rechten: Das Kindeswohl ist ein eigenständiges Rechtsgut, das Elternrechte und staatliche Interessen legitimerweise begrenzen darf.","Kindheit ist mehr als eine Vorbereitung auf das Erwachsensein.","Kinder haben eigene Rechte, die über die Interessen der Eltern gestellt werden können.","Das Kindeswohl schützt Kinder vor staatlicher und elterlicher Willkür."],"correctAnswer":"Kindheit ist keine vorübergehende Phase auf dem Weg zum Erwachsenenstatus, sondern eine eigenwertige Lebensphase mit eigener Logik und eigenen Rechten: Das Kindeswohl ist ein eigenständiges Rechtsgut, das Elternrechte und staatliche Interessen legitimerweise begrenzen darf."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kunst hat eine eigene Logik, die sich ökonomischem Kalkül ___.","options":["entzieht","widersetzt","entgegenstellt","verweigert"],"correctAnswer":"entzieht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Each science has its own methods and standards","wordBankItems":["Jede","Wissenschaft","hat","ihre","eigenen","Methoden","und","Maßstäbe","."],"correctAnswer":"Jede Wissenschaft hat ihre eigenen Methoden und Maßstäbe ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Rechtsgut'' means?","options":["legal good","protected right","legal value","protected interest"],"correctAnswer":"legal good"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002bb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss ageing and dignity at B2","Use Altern und Würde vocabulary","Talk about Germany''s ageing society, elderly care, and dignity in old age"],"explanation":{"intro":"Ageing and dignity vocabulary covers Germany''s ageing society, elderly care systems, and the dignity of old age at B2.","culturalNote":"Altern und Würde: Germany: extremely rapidly ageing society — median age ~47. Pflegebedürftigkeit (need for care — 5 million people). Pflegeversicherung (care insurance — fifth social insurance pillar — 1995). Pflegenotstand (care emergency — shortage of qualified staff). Altersarmut (old-age poverty — especially women — pension gaps). Demenz (dementia — 1.8 million in Germany). Nursing home (Pflegeheim) vs. ambulante Pflege (home care). Generationenvertrag (intergenerational contract — working generation pays for pensioners). Active ageing (Aktives Altern). ''Silberwirtschaft'' (silver economy — senior consumer market). Altersdiskriminierung (ageism). Key: Würde im Alter (dignity in old age — Art. 1 GG applies unconditionally)."},"examples":[{"german":"Eine Gesellschaft misst sich an ihrem Umgang mit den Schwächsten: Wie sie alte und pflegebedürftige Menschen behandelt, spiegelt ihre Wertvorstellungen wider. Würde im Alter ist kein Luxus, den nur Wohlhabende beanspruchen können, sondern eine grundlegende Verpflichtung, die im Menschenwürdebegriff des Grundgesetzes verankert ist.","english":"A society is measured by its treatment of the weakest: how it treats old and care-dependent people reflects its values. Dignity in old age is not a luxury that only the wealthy can claim, but a fundamental obligation that is anchored in the concept of human dignity in the Basic Law."},{"german":"Die Pflegekrise ist symptomatisch für ein strukturelles Versagen: Pflege wurde lange als ''natürlich weibliche'' Aufgabe konzipiert und entsprechend gering entlohnt, was zu einem chronischen Fachkräftemangel führt, der durch Anerkennung, Professionalisierung und faire Entlohnung behoben werden müsste.","english":"The care crisis is symptomatic of a structural failure: care was long conceived as a ''naturally feminine'' task and correspondingly poorly remunerated, which leads to a chronic skilled worker shortage that would need to be remedied through recognition, professionalisation, and fair remuneration."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s care crisis, ageing society, and dignity in old age at B2."}}',
'{"items":[{"word":"pflegebedürftig","translation":"in need of care","pronunciation":"PFLAY-geh-beh-dür-ftikh","example":"Pflegebedürftige Menschen."},{"word":"entsprechend","translation":"correspondingly","pronunciation":"ent-SHPREKH-end","example":"Entsprechend gering entlohnt."},{"word":"entlohnen","translation":"to remunerate","pronunciation":"ent-LOH-nen","example":"Gering entlohnt."},{"word":"chronisch","translation":"chronic","pronunciation":"KRO-nish","example":"Chronischer Mangel."},{"word":"beheben","translation":"to remedy","pronunciation":"beh-HEY-ben","example":"Mangel beheben."},{"word":"die Professionalisierung","translation":"professionalisation","pronunciation":"dee pro-fes-yo-nah-li-ZEE-roong","example":"Professionalisierung der Pflege."}]}',
'{"title":"Sich an X messen — to be measured by X (a standard of evaluation for a collective)","pattern":"eine Gesellschaft/Person misst sich an X = a society/person is measured by X, measures itself by X (sich messen an + dative = to be measured against, to hold oneself to the standard of X)","explanation":"Sich messen an + dative = to be measured by/against, to hold oneself to X as a standard. Eine Gesellschaft misst sich an ihrem Umgang mit den Schwächsten = A society is measured by its treatment of the weakest (dative: ihrem Umgang mit den Schwächsten — the standard of measurement). The phrase simultaneously describes evaluation from outside (''is measured by'') and self-evaluation (''measures itself by''). Often used to invoke a normative standard for collective evaluation. Compare: sich an X orientieren (to be oriented by X — aspirational), X als Maßstab nehmen (to take X as a standard — more deliberate), dem Anspruch von X gerecht werden (to do justice to the claim of X — more specific).","examples":[{"sentence":"Ein Unternehmen misst sich an seinen ethischen Standards.","translation":"A company is measured by its ethical standards."},{"sentence":"Politische Systeme messen sich an den Rechten, die sie garantieren.","translation":"Political systems are measured by the rights they guarantee."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Beheben'' means?","options":["to remedy","to fix","to solve","to resolve"],"correctAnswer":"to remedy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A society is measured by its treatment of the weakest: how it treats old and care-dependent people reflects its values. Dignity in old age is not a luxury that only the wealthy can claim, but a fundamental obligation that is anchored in the concept of human dignity in the Basic Law.","options":["Eine Gesellschaft misst sich an ihrem Umgang mit den Schwächsten: Wie sie alte und pflegebedürftige Menschen behandelt, spiegelt ihre Wertvorstellungen wider. Würde im Alter ist kein Luxus, den nur Wohlhabende beanspruchen können, sondern eine grundlegende Verpflichtung, die im Menschenwürdebegriff des Grundgesetzes verankert ist.","Wie eine Gesellschaft ihre Alten behandelt, zeigt ihre Werte.","Würde im Alter ist ein Grundrecht, kein Privileg.","Der Umgang mit Pflegebedürftigen ist ein Spiegel gesellschaftlicher Werte."],"correctAnswer":"Eine Gesellschaft misst sich an ihrem Umgang mit den Schwächsten: Wie sie alte und pflegebedürftige Menschen behandelt, spiegelt ihre Wertvorstellungen wider. Würde im Alter ist kein Luxus, den nur Wohlhabende beanspruchen können, sondern eine grundlegende Verpflichtung, die im Menschenwürdebegriff des Grundgesetzes verankert ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ein Unternehmen misst sich an seinen ethischen ___.","options":["Standards","Werten","Maßstäben","Grundsätzen"],"correctAnswer":"Standards"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Political systems are measured by the rights they guarantee","wordBankItems":["Politische","Systeme","messen","sich","an","den","Rechten",",","die","sie","garantieren","."],"correctAnswer":"Politische Systeme messen sich an den Rechten , die sie garantieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entsprechend'' means?","options":["correspondingly","accordingly","appropriately","proportionally"],"correctAnswer":"correspondingly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

-- Lesson 700: B2 milestone M6 (xp:200, coins:100)
INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002bc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss meaning and transcendence at B2","Use Sinn und Transzendenz vocabulary","Talk about the search for meaning, transcendence, and existential questions in German culture"],"explanation":{"intro":"Meaning and transcendence vocabulary covers philosophy of meaning, existential questions, and secular vs. religious approaches at B2.","culturalNote":"Sinn und Transzendenz: Key philosophical tradition: Viktor Frankl (Logotherapie — meaning as core human drive — ''Der Mensch sucht Sinn'' — meaning despite suffering). Camus (absurdism — Sisyphe — revolt against meaninglessness). Nietzsche (''God is dead'' — nihilism — will to power as meaning-creation). German: Sinnsuche (search for meaning), Sinnkrise (meaning crisis), Transzendenz (transcendence — going beyond the immanent). Key concept: Existenzielle Fragen (existential questions — What am I here for? What is worth living for?). Säkulare Sinngebung (secular meaning-making). Religion vs. Existenzialismus (religion vs. existentialism) as alternative meaning frameworks. Key phrase: ''Der Mensch ist das Wesen, das Sinn braucht'' — ''The human is the being that needs meaning''."},"examples":[{"german":"Sinnsuche ist eine anthropologische Konstante, keine religiöse Besonderheit: Auch in säkularen Gesellschaften orientieren Menschen ihr Handeln an Werten, Projekten und Beziehungen, die über unmittelbaren Eigennutz hinausgehen und dem Einzelleben ein Gewicht verleihen, das die bloße Zeitspanne von Geburt bis Tod übersteigt.","english":"The search for meaning is an anthropological constant, not a religious peculiarity: even in secular societies, people orient their actions by values, projects, and relationships that go beyond immediate self-interest and lend the individual life a weight that surpasses the mere timespan from birth to death."},{"german":"Transzendenz bedeutet nicht zwingend das Übernatürliche: In einem weiteren Sinn bezeichnet sie alles, was über die Grenzen des unmittelbar Gegebenen hinausgeht — Kunst, Liebe, Gerechtigkeit, Zukunft sind Formen säkularer Transzendenz, durch die der Mensch den Eigenwert seiner Gegenwart an einer Dimension misst, die sie übersteigt.","english":"Transcendence does not necessarily mean the supernatural: in a broader sense it designates everything that goes beyond the limits of the immediately given — art, love, justice, future are forms of secular transcendence through which the human measures the intrinsic value of their present against a dimension that surpasses it."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Viktor Frankl''s logotherapy, secular meaning-making, and secular transcendence at B2."}}',
'{"items":[{"word":"die Sinnsuche","translation":"search for meaning","pronunciation":"dee ZIN-zoo-kheh","example":"Menschliche Sinnsuche."},{"word":"anthropologisch","translation":"anthropological","pronunciation":"ant-ro-po-LOH-gish","example":"Anthropologische Konstante."},{"word":"der Eigennutz","translation":"self-interest","pronunciation":"dayr EYE-gen-noots","example":"Unmittelbarer Eigennutz."},{"word":"verleihen","translation":"to lend/confer","pronunciation":"fer-LY-en","example":"Dem Leben Gewicht verleihen."},{"word":"übersteigen","translation":"to surpass/exceed","pronunciation":"ü-ber-SHTY-gen","example":"Die Zeitspanne übersteigen."},{"word":"das Übernatürliche","translation":"the supernatural","pronunciation":"dahs ü-ber-nah-TÜR-li-kheh","example":"Übernatürliche Transzendenz."}]}',
'{"title":"Einem Leben Gewicht verleihen — to lend a life weight (conferring significance)","pattern":"etwas verleiht X + dative + Gewicht = something lends X weight/significance (verleihen = to lend/confer — irregular: verleiht/verlieh/verliehen; Gewicht = weight — here figurative: significance, gravity)","explanation":"Verleihen = to lend, confer (irregular: verleiht — 3rd person present; verlieh — simple past; verliehen — past participle). Dem Einzelleben Gewicht verleihen = to lend the individual life weight (dative: dem Einzelleben — what receives the weight; Gewicht = weight figuratively = significance). The image: a life has more ''weight'' when it is oriented beyond itself. Verleihen can collocate with many abstract nouns: Würde verleihen (to confer dignity), Bedeutung verleihen (to give meaning), Glaubwürdigkeit verleihen (to lend credibility). Compare: Bedeutung geben (to give meaning — more direct), bereichern (to enrich), aufwerten (to upgrade/enhance — more everyday).","examples":[{"sentence":"Der Einsatz für andere verleiht dem eigenen Leben Sinn.","translation":"Commitment to others lends one''s own life meaning."},{"sentence":"Erfahrungen verleihen einem Argument Gewicht.","translation":"Experiences lend an argument weight."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Anthropologisch'' means?","options":["anthropological","human","universal","existential"],"correctAnswer":"anthropological"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The search for meaning is an anthropological constant, not a religious peculiarity: even in secular societies, people orient their actions by values, projects, and relationships that go beyond immediate self-interest and lend the individual life a weight that surpasses the mere timespan from birth to death.","options":["Sinnsuche ist eine anthropologische Konstante, keine religiöse Besonderheit: Auch in säkularen Gesellschaften orientieren Menschen ihr Handeln an Werten, Projekten und Beziehungen, die über unmittelbaren Eigennutz hinausgehen und dem Einzelleben ein Gewicht verleihen, das die bloße Zeitspanne von Geburt bis Tod übersteigt.","Sinnsuche ist nicht religiös — auch säkulare Menschen suchen nach Bedeutung.","Der Mensch braucht Sinn, unabhängig davon, ob er religiös ist oder nicht.","Auch ohne Religion können Menschen ein sinnvolles Leben führen."],"correctAnswer":"Sinnsuche ist eine anthropologische Konstante, keine religiöse Besonderheit: Auch in säkularen Gesellschaften orientieren Menschen ihr Handeln an Werten, Projekten und Beziehungen, die über unmittelbaren Eigennutz hinausgehen und dem Einzelleben ein Gewicht verleihen, das die bloße Zeitspanne von Geburt bis Tod übersteigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Einsatz für andere verleiht dem eigenen Leben ___.","options":["Sinn","Bedeutung","Gewicht","Wert"],"correctAnswer":"Sinn"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Experiences lend an argument weight","wordBankItems":["Erfahrungen","verleihen","einem","Argument","Gewicht","."],"correctAnswer":"Erfahrungen verleihen einem Argument Gewicht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Übersteigen'' means?","options":["to surpass/exceed","to transcend","to go beyond","to top"],"correctAnswer":"to surpass/exceed"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

